import {escape as e,safeURL,shareButton,courseURL,postURL,readPreference,writePreference} from './ui.js';
let contact='2348059744860';
function gallery(c){const images=[...new Set([c.image||c.flyerUrl,...(c.images||[])].filter(Boolean))].slice(0,8);return `<div class="course-gallery"><img class="gallery-main" id="gallery-main" src="${e(safeURL(images[0],{image:true}))}" alt="${e(c.title)} — cover image" width="600" height="750">${images.length>1?`<div class="gallery-thumbs" aria-label="Choose a course image">${images.map((url,i)=>`<button type="button" data-gallery-image="${e(safeURL(url,{image:true}))}" aria-label="View image ${i+1}" aria-pressed="${i===0}"><img src="${e(safeURL(url,{image:true}))}" alt="Course image ${i+1}" loading="lazy" width="100" height="125"></button>`).join('')}</div>`:''}</div>`;}
function reviews(c){return `<section class="course-feedback"><h2>Student comments <em>& ratings.</em></h2><p id="rating-summary" class="status">Reviews are published after moderation.</p><div id="course-reviews" data-course="${e(c.id)}"><p>No published reviews yet. Share your learning experience.</p></div><details class="admin-card"><summary>Leave a comment & rating</summary><form id="review-form" data-course="${e(c.id)}"><label class="field">Your name<input name="name" maxlength="80" required autocomplete="name"></label><label class="field">Rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} ${n===1?'star':'stars'}</option>`).join('')}</select></label><label class="field">Your comment<textarea name="comment" minlength="10" maxlength="1500" required></textarea></label><label class="field check"><input type="checkbox" required>I agree to publish my name, comment and rating after moderation.</label><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><button class="btn" type="submit">Submit for review ↗</button><p class="status" data-form-status></p></form></details></section>`;}
function whatsapp(c){return 'https://wa.me/'+contact+'?text='+encodeURIComponent(`Hello Gracy, I am interested in ${c.title}. Please confirm the schedule, fees and requirements. Course: ${new URL(courseURL(c),location.origin).href}`);}
export function renderCourse(el,c){el.innerHTML=`<div class="course-layout"><div><p class="eyebrow">${e(c.duration||'ONLINE MASTERCLASS')} · ${e(c.level||'Skill builder')}</p><h1>${e(c.title)}</h1><p class="lede">${e(c.summary||'')}</p><div class="page-tools">${shareButton(c.title,courseURL(c))}</div><h2>A closer look <em>at the craft.</em></h2><p>${e(c.description||'')}</p><h3>Before you begin</h3><p>Confirm the schedule, materials, experience level and class access with Gracy before enrolling.</p><div class="notice">Pay through the academy’s Selar checkout. This website does not collect card details.</div>${reviews(c)}</div><aside class="course-aside">${gallery(c)}<p class="fee">${e(c.fee||'Ask Gracy')}</p><a class="btn" href="${e(safeURL(c.checkout||c.selarLink))}" target="_blank" rel="noopener noreferrer">Enrol through Selar ↗</a><a class="btn outline" href="${e(whatsapp(c))}" target="_blank" rel="noopener noreferrer">Ask about this class ↗</a><p class="status">Confirm current fees and availability.</p></aside></div>`;updateMetadata(c.title,c.summary||c.description,courseURL(c));}
export function enhancePublic(courses,posts,settings){if(/^\d{10,15}$/.test(settings?.whatsapp))contact=settings.whatsapp;const el=document.querySelector('#course-reviews'),id=el?.dataset.course,c=courses.find(x=>x.id===id);if(c){const aside=document.querySelector('.course-aside');if(aside&&!aside.querySelector('.course-gallery')){aside.querySelector('img')?.remove();aside.insertAdjacentHTML('afterbegin',gallery(c));}document.querySelectorAll('.course-aside [data-whatsapp]').forEach(a=>a.href=whatsapp(c));if(!document.querySelector('#rating-summary'))el.insertAdjacentHTML('beforebegin','<p id="rating-summary" class="status">Reviews are published after moderation.</p>');updateMetadata(c.title,c.summary||c.description,courseURL(c));}}
export function enhanceArticle(p){const article=document.querySelector('#live-article');if(!article)return;article.classList.remove('article-editorial','article-tutorial','article-field-notes');article.classList.add('article-'+(['tutorial','field-notes'].includes(p.articleStyle)?p.articleStyle:'editorial'));article.querySelector('.article-downloads')?.remove();const docs=Array.isArray(p.attachments)?p.attachments.slice(0,5):[];if(docs.length)article.insertAdjacentHTML('beforeend',`<section class="article-downloads"><p class="eyebrow">TAKE IT INTO YOUR PRACTICE</p><h2>From the studio, <em>to your workspace.</em></h2>${docs.map(a=>`<a class="document-download" href="${e(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">↓ ${e(a.name)} <span>Open document ↗</span></a>`).join('')}</section>`);updateMetadata(p.title,p.excerpt,postURL(p));}
function updateMetadata(title,description,url){document.title=title+' | ISew with Gracy';document.querySelector('meta[name="description"]')?.setAttribute('content',description||'');let canonical=document.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.append(canonical);}canonical.href=new URL(url,location.origin).href;for(const [name,value] of [['og:url',canonical.href],['og:title',document.title],['og:description',description||'']])document.querySelector(`meta[property="${name}"]`)?.setAttribute('content',value);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-gallery-image]');if(!b)return;const img=document.querySelector('#gallery-main');if(!img)return;img.src=b.dataset.galleryImage;img.alt=b.getAttribute('aria-label');b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
export function setupInstall(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;if(!ios||standalone)return;const help=document.querySelector('#install-instructions');if(help)help.innerHTML='<strong>Install on iPhone or iPad</strong><ol><li>Open this website in Safari.</li><li>Tap the Share button (square with an upward arrow). Depending on your Safari layout, Share may be inside the More menu.</li><li>Choose <strong>Add to Home Screen</strong>.</li><li>Enable <strong>Open as Web App</strong> if shown, then tap <strong>Add</strong>.</li></ol><p>The academy opens from its own Home Screen icon.</p>';if(!readPreference('isew-install-dismissed'))setTimeout(()=>{const bar=document.querySelector('#install-bar');if(bar&&!document.querySelector('dialog[open]')){bar.hidden=false;bar.querySelector('p').textContent='On iPhone: Safari → Share → Add to Home Screen.';}},18000);}
export function setupVideos(){document.addEventListener('click',async event=>{const button=event.target.closest('[data-play-video]');if(!button)return;const video=button.closest('.video-frame').querySelector('video');if(!video.src){video.src=video.dataset.src;video.load();}video.controls=true;try{await video.play();button.hidden=true;}catch{button.textContent='Tap to play';}video.addEventListener('error',()=>{button.hidden=false;button.textContent='Playback unavailable. Tap to retry.';},{once:true});});document.addEventListener('play',event=>{if(event.target.tagName==='VIDEO')document.querySelectorAll('video').forEach(v=>{if(v!==event.target)v.pause();});},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause());});}
